package auth

import (
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

func (m Model) InEditMode() bool {
	// En mode édition seulement si un textinput a le focus (champs 0 ou 1)
	// et que l'utilisateur n'est pas en train d'authentifier
	// Si authentifié, on n'est plus en mode édition
	if m.authenticated || m.authenticating {
		return false
	}
	// En mode édition si on est sur un des champs de texte
	return m.currentField == 0 || m.currentField == 1
}

func (m Model) GetShortcuts() shortcut.Shortcuts {
	return []shortcut.Shortcut{
		{Key: "enter", Description: "Submit / Advance field"},
		{Key: "space", Description: "Select option"},
		{Key: "ctrl+s", Description: "Toggle save to helper"},
		{Key: "ctrl+f", Description: "Toggle save to config"},
		{Key: "alt+:", Description: "Command mode"},
		{Key: "?", Description: "Help"},
	}
}

// GetFooterHeight returns the footer height for this view (Rule 124).
func (m Model) GetFooterHeight() int {
	return 2 // empty line + info line
}

// RenderFooter returns the footer content rendered below the viewport (Rule 124).
func (m Model) RenderFooter(width int) string {
	return theme.EmptyLineBg(width) + "\n" + theme.EmptyLineBg(width)
}

func (m Model) GetTitle() string {
	return theme.IconUser + " Gitlab Authentication"
}

func (m Model) GetIcon() string {
	return ""
}

// GetHeaderInfo returns the key-value info for the header
func (m Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
	return []shortcut.HeaderInfo{
		{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
	}
}

// GetHelpContent retourne le contenu d'aide de la vue GitLab Auth
func (m Model) GetHelpContent() help.Content {
	return help.Content{
		Title:       "GitLab Authentication",
		Description: "This view allows you to connect to a GitLab instance. Once authenticated, you can explore groups and projects, clone repositories, and manage your GitLab resources.",
		KeyBindings: []help.KeyBinding{
			{Key: "↑ / ↓", Description: "Navigate between form fields"},
			{Key: "enter", Description: "Submit form / advance to next field"},
			{Key: "space", Description: "Select save option"},
			{Key: "ctrl+s", Description: "Toggle save to Git Credential Manager"},
			{Key: "ctrl+f", Description: "Toggle save to config file"},
			{Key: "alt+:", Description: "Open command mode"},
			{Key: "?", Description: "Show this help"},
		},
		Sections: []help.Section{
			{
				Title: "Save Options",
				Body:  "Git Credential Manager (recommended): stores the token securely via Git's credential helper. The token does not appear in configuration files.\n\nConfig file: saves the token in ~/.devdesk/contexts/<context>/config.yaml. Less secure but works without a credential helper.",
			},
			{
				Title: "Personal Access Token",
				Body:  "Create a token in GitLab > Settings > Access Tokens. Required scopes: api, read_user. The token must start with 'glpat-'.",
			},
		},
	}
}

// View rend la vue
func (m *Model) View() string {
	var sections []string

	// Status (only show when not authenticated, to avoid duplication with logged-in view)
	if m.success != "" && !m.authenticated {
		sections = append(sections, m.renderSuccess())
	}

	// Warning (non-bloquant, ex: échec sauvegarde credentials)
	if m.warning != "" {
		sections = append(sections, m.renderWarning())
	}

	// Form
	sections = append(sections, m.renderForm())

	// Error
	if m.error != "" {
		sections = append(sections, m.renderError())
	}

	return lipgloss.NewStyle().Background(theme.ColorBackground).Padding(1).Render(strings.Join(sections, "\n"))
}

func (m *Model) renderForm() string {
	var b strings.Builder

	// Spinner si en cours d'authentification
	if m.authenticating {
		b.WriteString(theme.SpinnerMessage(m.spinner.View(), "Authenticating...") + "\n\n")
		return lipgloss.NewStyle().Background(theme.ColorBackground).Padding(1, 2).Render(b.String())
	}

	// Si authentifié, afficher la vue "Logged in"
	if m.authenticated && m.user != nil {
		return m.renderLoggedInView()
	}

	// Sinon, afficher le formulaire de login
	// URL
	labelStyle := lipgloss.NewStyle().Background(theme.ColorBackground).Bold(true)
	if m.currentField == 0 {
		labelStyle = labelStyle.Foreground(theme.ColorPrimary)
	}
	b.WriteString(labelStyle.Render("GitLab URL") + "\n")
	b.WriteString(m.urlInput.View() + "\n\n")

	// Token
	labelStyle = lipgloss.NewStyle().Background(theme.ColorBackground).Bold(true)
	if m.currentField == 1 {
		labelStyle = labelStyle.Foreground(theme.ColorPrimary)
	}
	b.WriteString(labelStyle.Render("Personal Access Token") + "\n")
	b.WriteString(m.tokenInput.View() + "\n\n")

	// Options
	b.WriteString(theme.DimStyle.Render("Save options:") + "\n")

	b.WriteString(theme.RenderRadioButton(m.saveOption == SaveToHelper, "Save to Git Credential Manager (secure)", m.currentField == 2) + "\n")
	b.WriteString(theme.RenderRadioButton(m.saveOption == SaveToConfig, "Save token to config file (less secure)", m.currentField == 3) + "\n\n")

	// Button
	b.WriteString(theme.RenderButton("Login", m.currentField == 4, "primary"))

	return lipgloss.NewStyle().Background(theme.ColorBackground).Padding(1, 2).Render(b.String())
}

func (m *Model) renderLoggedInView() string {
	var b strings.Builder

	// Afficher les infos de l'utilisateur
	b.WriteString(lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Bold(true).Render("Authenticated as: "))
	b.WriteString(lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorPrimary).Bold(true).Render(m.user.Username))
	if m.user.Name != "" {
		b.WriteString(theme.Bg(" (" + m.user.Name + ")"))
	}
	b.WriteString("\n")

	// Afficher l'URL GitLab
	if m.config != nil && m.config.GitLab.URL != "" {
		b.WriteString(lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Bold(true).Render("GitLab URL: "))
		b.WriteString(lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorPrimary).Bold(true).Render(m.config.GitLab.URL) + "\n")
	}
	b.WriteString("\n")

	// Bouton Logout
	b.WriteString(theme.RenderButton("Logout", m.currentField == 0, "danger"))

	return lipgloss.NewStyle().Background(theme.ColorBackground).Padding(1, 2).Render(b.String())
}

func (m *Model) renderSuccess() string {
	style := lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorOK).
		Padding(1, 2)
	return style.Render(m.success)
}

func (m *Model) renderWarning() string {
	style := lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorError).
		Padding(1, 2).
		Width(m.width - 8)
	return style.Render(theme.IconWarning + " " + m.warning)
}

func (m *Model) renderError() string {
	style := lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorError).
		Padding(1, 2)
	return style.Render("✗ " + m.error)
}

package docker

import (
	"encoding/base64"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
)

// dockerHubKeys lists all keys Docker uses for Docker Hub in ~/.docker/config.json.
// `docker login docker.io` stores credentials under "https://index.docker.io/v1/".
var dockerHubKeys = []string{
	"docker.io",
	"registry-1.docker.io",
	"https://index.docker.io/v1/",
	"https://index.docker.io/v1",
	"https://registry-1.docker.io",
}

// registryCandidates returns all URL variants to look up in ~/.docker/config.json.
func registryCandidates(registryURL string) []string {
	base := strings.TrimSuffix(registryURL, "/")

	// Check if this URL is any known Docker Hub alias; if so, return the full set.
	for _, alias := range dockerHubKeys {
		if strings.EqualFold(base, strings.TrimSuffix(alias, "/")) {
			return dockerHubKeys
		}
	}

	// Generic: bare hostname, https://, http:// variants.
	candidates := []string{base}
	if strings.HasPrefix(base, "https://") {
		candidates = append(candidates, strings.TrimPrefix(base, "https://"))
	} else if strings.HasPrefix(base, "http://") {
		candidates = append(candidates, strings.TrimPrefix(base, "http://"))
	} else {
		candidates = append(candidates, "https://"+base, "http://"+base)
	}
	return candidates
}

// dockerConfigPath returns the path to ~/.docker/config.json.
func dockerConfigPath() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".docker", "config.json"), nil
}

// readDockerConfig reads and unmarshals ~/.docker/config.json into v.
func readDockerConfig(v any) error {
	path, err := dockerConfigPath()
	if err != nil {
		return err
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	return json.Unmarshal(data, v)
}

// RegistryLogin authenticates with a Docker/OCI registry using `docker login`.
// The password is passed via stdin to avoid exposing it in the process list.
func RegistryLogin(registryURL, username, password string) error {
	if err := requireDocker(); err != nil {
		return err
	}
	output, err := runner.Run(dockerCmd{
		Args:     []string{"login", registryURL, "-u", username, "--password-stdin"},
		Stdin:    password,
		Combined: true,
	})
	if err != nil {
		return errWithOutput("docker login", output)
	}
	return nil
}

// IsRegistryLoggedIn reports whether stored credentials exist for registryURL
// by inspecting ~/.docker/config.json.
func IsRegistryLoggedIn(registryURL string) bool {
	var cfg struct {
		Auths map[string]json.RawMessage `json:"auths"`
	}
	if err := readDockerConfig(&cfg); err != nil {
		return false
	}
	for _, c := range registryCandidates(registryURL) {
		if _, ok := cfg.Auths[c]; ok {
			return true
		}
	}
	return false
}

// RegistryLogout removes stored credentials for a Docker/OCI registry.
// It runs `docker logout` (cleans system credential stores) then directly
// removes all matching keys from ~/.docker/config.json to handle cases where
// docker logout leaves behind alias entries (e.g. docker.io vs https://index.docker.io/v1/).
func RegistryLogout(registryURL string) error {
	if err := requireDocker(); err != nil {
		return err
	}
	if err := mutate("docker logout", "logout", registryURL); err != nil {
		return err
	}
	// Also remove all matching alias keys directly from config.json.
	_ = removeFromDockerConfig(registryURL)
	return nil
}

// removeFromDockerConfig removes all URL variants of registryURL from the auths
// section of ~/.docker/config.json. Errors are non-fatal (best effort).
func removeFromDockerConfig(registryURL string) error {
	configPath, err := dockerConfigPath()
	if err != nil {
		return err
	}

	var raw map[string]json.RawMessage
	if err := readDockerConfig(&raw); err != nil {
		return err
	}
	authsRaw, ok := raw["auths"]
	if !ok {
		return nil
	}
	var auths map[string]json.RawMessage
	if err := json.Unmarshal(authsRaw, &auths); err != nil {
		return err
	}

	changed := false
	for _, candidate := range registryCandidates(registryURL) {
		if _, exists := auths[candidate]; exists {
			delete(auths, candidate)
			changed = true
		}
	}
	if !changed {
		return nil
	}

	updated, err := json.Marshal(auths)
	if err != nil {
		return err
	}
	raw["auths"] = updated
	out, err := json.MarshalIndent(raw, "", "\t")
	if err != nil {
		return err
	}
	return os.WriteFile(configPath, out, 0600)
}

// GetStoredCreds retrieves Docker credentials for registryURL from
// ~/.docker/config.json. It tries the per-registry credential helper
// (credHelpers), then the global credsStore, and finally falls back to the
// inline base64-encoded auth field. Returns ok=false when no credentials are
// found.
func GetStoredCreds(registryURL string) (username, password string, ok bool) {
	var cfg struct {
		Auths map[string]struct {
			Auth string `json:"auth"`
		} `json:"auths"`
		CredsStore  string            `json:"credsStore"`
		CredHelpers map[string]string `json:"credHelpers"`
	}
	if err := readDockerConfig(&cfg); err != nil {
		return "", "", false
	}

	// Normalise the URL to a bare hostname for helper lookups.
	hostname := strings.TrimSuffix(registryURL, "/")
	for _, prefix := range []string{"https://", "http://"} {
		hostname = strings.TrimPrefix(hostname, prefix)
	}

	helper := cfg.CredHelpers[hostname]
	if helper == "" {
		helper = cfg.CredsStore
	}
	if helper != "" {
		if u, p, ok := getCredsFromHelper(helper, hostname); ok {
			return u, p, true
		}
	}

	for _, candidate := range registryCandidates(registryURL) {
		if entry, ok := cfg.Auths[candidate]; ok && entry.Auth != "" {
			if u, p, ok := decodeAuth(entry.Auth); ok {
				return u, p, true
			}
		}
	}
	return "", "", false
}

// decodeAuth splits a base64 "username:password" auth field.
func decodeAuth(auth string) (username, password string, ok bool) {
	decoded, err := base64.StdEncoding.DecodeString(auth)
	if err != nil {
		return "", "", false
	}
	if idx := strings.IndexByte(string(decoded), ':'); idx >= 0 {
		return string(decoded[:idx]), string(decoded[idx+1:]), true
	}
	return "", "", false
}

// getCredsFromHelper calls `docker-credential-<helper> get` and parses the JSON response.
func getCredsFromHelper(helper, serverURL string) (username, password string, ok bool) {
	out, err := runner.Run(dockerCmd{
		Args:   []string{"get"},
		Stdin:  serverURL,
		Helper: helper,
	})
	if err != nil {
		return "", "", false
	}
	var result struct {
		Username string `json:"Username"`
		Secret   string `json:"Secret"`
	}
	if err := json.Unmarshal(out, &result); err != nil {
		return "", "", false
	}
	if result.Secret == "" {
		return "", "", false
	}
	return result.Username, result.Secret, true
}

// RegistryAlias pairs a URL prefix with a short alias for display purposes.
type RegistryAlias struct {
	URL   string
	Alias string
}

// ApplyAliases replaces registry URL prefixes in an image name with their configured alias.
// Example: URL="gitlab.com/my-group", Alias="gl" turns
// "gitlab.com/my-group/my-image:1.0" into "gl/my-image:1.0".
func ApplyAliases(imageName string, aliases []RegistryAlias) string {
	for _, a := range aliases {
		if a.Alias == "" || a.URL == "" {
			continue
		}
		prefix := strings.TrimSuffix(a.URL, "/") + "/"
		if strings.HasPrefix(imageName, prefix) {
			return a.Alias + "/" + strings.TrimPrefix(imageName, prefix)
		}
	}
	return imageName
}

package ociresources

import (
	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/table"
	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// browserState tracks which screen the browser is on.
type browserState int

const (
	browserStateInput     browserState = iota // search form
	browserStateTags                          // results table
	browserStateStatus                        // spinner during pull
	browserStateResolving                     // detecting group members
)

// browserRegistryEntry is one selectable registry in the browser form.
// Group members have ParentAlias set; normal registries have it empty.
type browserRegistryEntry struct {
	URL         string
	Alias       string
	ParentAlias string // non-empty = member of a group
	parentURL   string // URL of the parent RegistryItem (for credential lookup)
}

const brFieldRepo = 0

// brFieldReg returns the form field index for the i-th registry checkbox.
func (b *RegistryBrowser) brFieldReg(i int) int { return 1 + i }

// brFieldSubmit returns the form field index for the Browse Tags button.
func (b *RegistryBrowser) brFieldSubmit() int { return 1 + len(b.entries) }

// RegistryBrowserCloseMsg is sent when the user presses ESC on the browser input screen.
type RegistryBrowserCloseMsg struct{}

// tagSortField selects which column to sort the tag list by.
type tagSortField int

const (
	tagSortByName    tagSortField = iota
	tagSortByUpdated              // newest first
)

// RegistryBrowser searches image tags across multiple configured registries.
type RegistryBrowser struct {
	registries    []config.RegistryItem
	width, height int

	// Group detection state
	entryGroups       [][]browserRegistryEntry // one slot per registry, filled as detections complete
	entries           []browserRegistryEntry   // flattened from entryGroups after all detections
	pendingDetections int

	// Form state
	repoInput    textinput.Model
	selectedRegs map[string]bool // entry URL → checked
	focusedField int

	// Results state
	tags              []MultiRegistryTag
	pendingSearches   int
	registryFilter    string // "" = all, otherwise filter by RegistryURL
	tagTable          table.Model
	scanCache         map[string]cache.ImageScanEntry
	scanningTags      map[string]bool
	tagScanSpinnerIdx int

	// Tag filter/sort in results view
	filterInput  textinput.Model
	filterActive bool
	tagSortCol   tagSortField
	tagSortDesc  bool

	// Status screen (pull operation)
	spinner   spinner.Model
	operation string
	imageName string

	state browserState
}

// newRegistryBrowser creates a RegistryBrowser and fires group-detection commands for all
// configured registries. The browser starts in browserStateResolving until all detections
// complete; it then transitions to browserStateInput with the resolved entry list.
func newRegistryBrowser(registries []config.RegistryItem, width, height int) (*RegistryBrowser, tea.Cmd) {
	repoInput := textinput.New()
	repoInput.Placeholder = "nginx  (or library/nginx)"
	repoInput.CharLimit = 256
	theme.StyleTextInput(&repoInput)
	repoInput.Focus()

	fi := textinput.New()
	fi.Placeholder = "filter tags…"
	fi.CharLimit = 128
	theme.StyleTextInput(&fi)

	tagCols := []table.Column{
		{Title: "Registry", Width: 20},
		{Title: "Tag", Width: 30},
		{Title: "Updated", Width: 16},
		{Title: "C", Width: 4},
		{Title: "H", Width: 4},
		{Title: "M", Width: 4},
		{Title: "L", Width: 4},
	}
	tt := table.New(
		table.WithColumns(tagCols),
		table.WithFocused(true),
		table.WithHeight(10),
	)
	tt.SetStyles(theme.DefaultTableStyles())

	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = theme.SpinnerStyle()

	b := &RegistryBrowser{
		registries:        registries,
		entryGroups:       make([][]browserRegistryEntry, len(registries)),
		pendingDetections: len(registries),
		width:             width,
		height:            height,
		repoInput:         repoInput,
		selectedRegs:      make(map[string]bool),
		focusedField:      brFieldRepo,
		filterInput:       fi,
		tagSortCol:        tagSortByName,
		tagSortDesc:       false,
		tagTable:          tt,
		spinner:           sp,
		scanCache:         make(map[string]cache.ImageScanEntry),
		scanningTags:      make(map[string]bool),
		state:             browserStateResolving,
	}
	b.resizeInputs()
	b.resizeTagTable()

	if len(registries) == 0 {
		b.state = browserStateInput
		return b, nil
	}

	cmds := make([]tea.Cmd, 0, len(registries)+1)
	for _, reg := range registries {
		cmds = append(cmds, detectRegistryGroupCmd(reg, ""))
	}
	cmds = append(cmds, sp.Tick)
	return b, tea.Batch(cmds...)
}

// SetSize updates dimensions and resizes internal components.
func (b *RegistryBrowser) SetSize(width, height int) {
	b.width = width
	b.height = height
	b.resizeInputs()
	b.resizeTagTable()
}

// HandleGroupDetected incorporates one detection result into the ordered entry list.
// When all detections have completed it finalizes entries and switches to input state.
func (b *RegistryBrowser) HandleGroupDetected(msg RegistryGroupDetectedMsg) (*RegistryBrowser, tea.Cmd) {
	for i, reg := range b.registries {
		if reg.URL != msg.RegistryURL {
			continue
		}
		alias := reg.Alias
		if alias == "" {
			alias = reg.URL
		}
		if len(msg.Members) > 0 {
			group := make([]browserRegistryEntry, len(msg.Members))
			for j, m := range msg.Members {
				group[j] = browserRegistryEntry{
					URL:         m.URL,
					Alias:       m.Alias,
					ParentAlias: alias,
					parentURL:   reg.URL,
				}
			}
			b.entryGroups[i] = group
		} else {
			b.entryGroups[i] = []browserRegistryEntry{{URL: reg.URL, Alias: alias}}
		}
		break
	}
	b.pendingDetections--
	if b.pendingDetections <= 0 {
		b.finalizeEntries()
	}
	return b, nil
}

// finalizeEntries flattens entryGroups into entries, initialises selectedRegs (all checked),
// and transitions the browser to the input form state.
func (b *RegistryBrowser) finalizeEntries() {
	b.entries = nil
	for _, group := range b.entryGroups {
		b.entries = append(b.entries, group...)
	}
	b.selectedRegs = make(map[string]bool, len(b.entries))
	for _, e := range b.entries {
		b.selectedRegs[e.URL] = true
	}
	b.state = browserStateInput
	b.updateFocus()
}

func (b *RegistryBrowser) resizeInputs() {
	w := max(b.width-22, 20)
	b.repoInput.Width = w
	b.filterInput.Width = max(b.width-6, 10)
}

func (b *RegistryBrowser) resizeTagTable() {
	b.tagTable.SetHeight(max(b.height, 1))

	// b.width is already the viewport content width (full width - 2 borders).
	// Subtract only the cell padding (numCols × 2) so column widths sum exactly to `available`.
	const numCols = 7
	available := max(b.width-numCols*2, 10)
	fixedReg := 20
	fixedUpdated := 16
	fixedC, fixedH, fixedM := 4, 4, 4
	fixedSum := fixedReg + fixedUpdated + fixedC + fixedH + fixedM
	flexTag := max(available-fixedSum-4, 8) // reserve 4 for last col minimum

	cols := b.tagTable.Columns()
	if len(cols) == numCols {
		cols[0].Width = fixedReg
		cols[1].Width = flexTag
		cols[2].Width = fixedUpdated
		cols[3].Width = fixedC
		cols[4].Width = fixedH
		cols[5].Width = fixedM
		// Last column absorbs leftover so sum(col_widths) == available exactly.
		cols[6].Width = available - fixedReg - flexTag - fixedUpdated - fixedC - fixedH - fixedM
		b.tagTable.SetColumns(cols)
	}

	// Force the Selected row style to span the viewport content width so the selected
	// background extends to the right border, even when row content visually differs
	// from the calculated width (e.g. Nerd Font icon width discrepancies). See workspaces fix.
	styles := theme.DefaultTableStyles()
	styles.Selected = styles.Selected.Width(b.width)
	b.tagTable.SetStyles(styles)
}

